import os
import io
import datetime
import threading
import json
import logging
from collections import defaultdict
import fastavro
from kafka import KafkaProducer
from kafka.errors import NoBrokersAvailable


class RobotListener(object):
    ROBOT_LISTENER_API_VERSION = 2
    RESERVATION_CONTEXT_FILE_PATH = "/opt/ute/reservation.context.json"
    _soothing_message = "Note: test execution is NOT AFFECTED by this error."

    def __init__(self, topic="cm-test-execution-avro"):
        self._should_log_no_tc_id = True
        self.topic = topic
        bootstrap_servers = [
            "kafka-0.taf.nsn-rdnet.net",
            "kafka-1.taf.nsn-rdnet.net",
            "kafka-2.taf.nsn-rdnet.net",
        ]
        ca_cert_path = os.path.join(os.path.dirname(__file__), "resources", "ca-cert")
        try:
            self.producer = KafkaProducer(
                bootstrap_servers=bootstrap_servers,
                security_protocol="SASL_SSL",
                sasl_mechanism="PLAIN",
                sasl_plain_username="tafrobotlistener",
                sasl_plain_password="fyOcQO2EPlLUdUoI",
                ssl_cafile=ca_cert_path,
                request_timeout_ms=2000,
                max_block_ms=2000,
            )
        except NoBrokersAvailable:
            logging.warning(
                "Cannot instantiate Robot Listener. Cannot connect to kafka brokers. "
                + self._soothing_message
            )
            self._stop_listener()
            return

        self.cm_execution_id = os.getenv("CM_EXECUTION_ID")
        if self.cm_execution_id is None:
            logging.warning(
                "Cannot instantiate Robot Listener. Missing `CM_EXECUTION_ID` "
                "environment variable. " + self._soothing_message
            )
            self._stop_listener()
            return

        self.utc_offset_timedelta = datetime.datetime.utcnow() - datetime.datetime.now()
        self.epoch = datetime.datetime.utcfromtimestamp(0)
        self.schemas = self.load_schemas()
        self.testline_name = self.extract_testline_name()
        if self.testline_name is None:
            self._stop_listener()
            return

    def _stop_listener(self):
        """Disables the listener by destroying all the interface methods defined in
        https://robotframework.org/robotframework/latest/RobotFrameworkUserGuide.html#listener-version-2"""
        methods = (
            "start_suite",
            "end_suite",
            "start_test",
            "end_test",
            "start_keyword",
            "end_keyword",
            "log_message",
            "message",
            "library_import",
            "resource_import",
            "variables_import",
            "output_file",
            "log_file",
            "report_file",
            "xunit_file",
            "debug_file",
            "close",
        )
        for method in methods:
            setattr(self, method, None)

    def start_suite(self, name, attrs):
        start_time = self.convert_time(attrs["starttime"])
        data = {
            "execution_id": self.cm_execution_id,
            "testline_name": self.testline_name,
            "name": name,
            "startTime": start_time,
        }
        thread = threading.Thread(
            target=self.send_serialized, args=("start_suite", [data])
        )
        thread.start()
        return thread

    def _extract_test_case_id(self, attrs):
        """ Extracts test case id from the ute:id tag"""
        ute_id = "ute:id:"

        try:
            tag = next(tag for tag in attrs["tags"] if tag.startswith(ute_id))
            return tag.split(ute_id)[-1]
        except (StopIteration, KeyError):
            if self._should_log_no_tc_id:
                logging.warning(
                    "Cannot extract test case id from the test tag. ute:id tag was not found. "
                    "Further errors of this kind will be ignored. "
                    "Test case id will be passed as an empty string."
                    + self._soothing_message
                )
            self._should_log_no_tc_id = False
            return ""

    def start_test(self, name, attrs):
        test_case_id = self._extract_test_case_id(attrs)
        start_time = self.convert_time(attrs["starttime"])
        data = {
            "execution_id": self.cm_execution_id,
            "testline_name": self.testline_name,
            "name": name,
            "longName": attrs["longname"],
            "startTime": start_time,
            "test_case_id": test_case_id,
        }
        thread = threading.Thread(
            target=self.send_serialized, args=("start_test", [data])
        )
        thread.start()
        return thread

    def end_test(self, name, attrs):
        test_case_id = self._extract_test_case_id(attrs)
        start_time = self.convert_time(attrs["starttime"])
        end_time = self.convert_time(attrs["endtime"])
        data = {
            "execution_id": self.cm_execution_id,
            "testline_name": self.testline_name,
            "name": name,
            "longName": attrs["longname"],
            "startTime": start_time,
            "endTime": end_time,
            "elapsedTime": attrs["elapsedtime"],
            "result": attrs["status"],
            "test_case_id": test_case_id,
        }
        thread = threading.Thread(
            target=self.send_serialized, args=("end_test", [data])
        )
        thread.start()
        return thread

    def end_suite(self, name, attrs):
        start_time = self.convert_time(attrs["starttime"])
        end_time = self.convert_time(attrs["endtime"])
        data = {
            "execution_id": self.cm_execution_id,
            "testline_name": self.testline_name,
            "name": name,
            "startTime": start_time,
            "endTime": end_time,
            "elapsedTime": attrs["elapsedtime"],
            "result": attrs["status"],
        }
        thread = threading.Thread(
            target=self.send_serialized, args=("end_suite", [data])
        )
        thread.start()
        return thread

    def send_serialized(self, schema_name, data):
        raw_bytes = self.serialize(schema_name, data)
        self.send(raw_bytes)

    def serialize(self, schema_name, data):
        bytes_writer = io.BytesIO()
        fastavro.writer(bytes_writer, self.schemas[schema_name], data)
        return bytes_writer.getvalue()

    def send(self, raw_bytes):
        self.producer.send(self.topic, raw_bytes)
        self.producer.flush()

    def convert_time(self, time):
        local_datetime = datetime.datetime.strptime(time, "%Y%m%d %H:%M:%S.%f")
        result_utc_datetime = local_datetime + self.utc_offset_timedelta
        time_since_epoch = (result_utc_datetime - self.epoch).total_seconds() * 1000
        return int(time_since_epoch)

    def load_schemas(self):
        schemas_list = ["start_suite", "start_test", "end_test", "end_suite"]
        schemas = defaultdict(dict)
        for schema_name in schemas_list:
            schema_path = os.path.join(os.path.dirname(__file__), "resources", schema_name + ".avsc")
            with open(schema_path) as schema:
                schema = schema.read()
            schema_dict = json.loads(schema)
            schemas[schema_name] = schema_dict
        return schemas

    def extract_testline_name(self):
        if not os.path.exists(self.RESERVATION_CONTEXT_FILE_PATH):
            logging.warning(
                "Cannot instantiate Robot Listener. "
                "Missing {file_path} file.\n{note}".format(
                    file_path=self.RESERVATION_CONTEXT_FILE_PATH,
                    note=self._soothing_message)
            )
            return None
        with open(self.RESERVATION_CONTEXT_FILE_PATH) as f:
            data = json.load(f)
            try:
                return data["CM_RESOURCES"][0]["properties"]["name"]
            except KeyError:
                logging.warning(
                    "Cannot instantiate Robot Listener. "
                    "Testline name not found inside {file_path}. "
                    "File content:\n{file_content}\n{note}".format(
                        file_path=self.RESERVATION_CONTEXT_FILE_PATH,
                        file_content=data,
                        note=self._soothing_message)
                )
                return None
